/**
 * How Three water plantains (`mitsu-omodaka`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/mitsu-omodaka";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Three heads of three slender pointed lobes each: a central head, larger and lower, whose lobes point up, down to the left and down to the right, over a head each side that stands higher, with a spray of five round florets on twigs on each side of each of the side heads. Each lobe is the lens between two arcs, with a white vein, and a small ring stands where a head's lobes meet. A bar for the stalk runs down from the central ring and a thin curved band lies behind the heads. The band and the stalk are built first, then the sprays, then the central head, then the side heads cut a white line short of it.","ja":"細くとがった三つの裂片をもつ頭を三つ置きます。真ん中の頭は大きくて低く、裂片を上、左下、右下に向け、高いところに立つ左右の頭の上に重なります。左右の頭の両側には、五つの丸い花をつけた枝を一本ずつ添えます。裂片はどれも二つの弧にはさまれた形で、白い葉脈を一本通し、頭の裂片が出会うところに小さな輪を置きます。茎は中央の輪から下へ伸びる棒で、頭の後ろに細く曲がった帯を置きます。帯と茎、枝、真ん中の頭、左右の頭（真ん中の頭から白い線一本分だけ離して切ります）の順に作図します。"};

export default construction;
export { construction, description };
